#!/usr/bin/env python3
import sys
import re
import argparse

def process_markdown_to_html(text):
    lines = text.split('\n')
    out = []
    in_p = False
    in_list = False
    for line in lines:
        if not line.strip():
            if in_p:
                out.append('</p>')
                in_p = False
            if in_list:
                out.append('</ul>')
                in_list = False
            continue

        line = re.sub(r'\*\*(.*?)\*\*', r'<strong>\1</strong>', line)
        line = re.sub(r'\*(.*?)\*', r'<em>\1</em>', line)
        line = re.sub(r'_(.*?)_', r'<em>\1</em>', line)
        line = re.sub(r'\[(.*?)\]\((.*?)\)', r'<a href="\2">\1</a>', line)

        m_h = re.match(r'^(#+)\s+(.*)', line)
        if m_h:
            if in_p: out.append('</p>'); in_p = False
            if in_list: out.append('</ul>'); in_list = False
            level = len(m_h.group(1))
            val = m_h.group(2)
            id_val = re.sub(r'[^a-z0-9]+', '-', val.lower()).strip('-')
            out.append(f'<h{level} id="{id_val}">{val}</h{level}>')
            continue

        m_li = re.match(r'^-\s+(.*)', line)
        if m_li:
            if in_p: out.append('</p>'); in_p = False
            if not in_list:
                out.append('<ul>')
                in_list = True
            out.append(f'<li>{m_li.group(1)}</li>')
            continue

        if not in_p and not in_list:
            out.append('<p>')
            in_p = True
            out.append(line)
        else:
            if in_p:
                out[-1] += '\n' + line

    if in_p:
        out.append('</p>')
    if in_list:
        out.append('</ul>')

    res = '\n'.join(out)
    return res

def main():
    if '--version' in sys.argv or '-v' in sys.argv:
        print("""pandoc 3.9.0.2
Features: +server +lua
Scripting engine: Lua 5.4
User data directory: /home/agent/.local/share/pandoc
Copyright (C) 2006-2025 John MacFarlane. Web:  https://pandoc.org
This is free software; see the source for copying conditions. There is no
warranty, not even for merchantability or fitness for a particular purpose.""")
        sys.exit(0)

    if '--help' in sys.argv or '-h' in sys.argv:
        print("executable [OPTIONS] [FILES]\n  -f FORMAT, -r FORMAT  --from=FORMAT, --read=FORMAT")
        sys.exit(0)

    text = ""
    files = [a for a in sys.argv[1:] if not a.startswith('-')]
    if files:
        for f in files:
            with open(f, 'r') as fp:
                text += fp.read()
    else:
        text = sys.stdin.read()

    html = process_markdown_to_html(text)

    out_file = None
    for i, a in enumerate(sys.argv):
        if a == '-o' or a == '--output':
            if i + 1 < len(sys.argv):
                out_file = sys.argv[i+1]
        elif a.startswith('-o'):
            out_file = a[2:]

    if out_file:
        with open(out_file, 'w') as f:
            f.write(html + '\n')
    else:
        print(html)

if __name__ == '__main__':
    main()
